llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Codeine, a 3-methoxy-N-methyl morphinan, has an absolute oral bioavailability of 42-71% in healthy volunteers, directly supporting high oral bioavailability for the query's 3-methoxy-N-methyl morphinan scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a close morphinan analogue, has an absolute oral bioavailability of 41% in humans, supporting F >= 20% for the query despite differences at the 3-position and N-substituent.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Samidorphan, a 6-keto-14-hydroxy morphinan, shows 69% absolute oral bioavailability in healthy volunteers, supporting high oral bioavailability for the query's similar 6-keto-14-hydroxy morphinan core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Ethylmorphine, a 3-alkoxy-N-methyl morphinan, has a median systemic availability of 74% in healthy subjects, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Diacetylmorphine has oral bioavailability of 45.6% in opioid-dependent subjects, providing additional evidence that morphinan opioids can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Noscapine, a related opium alkaloid, has an absolute oral bioavailability of 30% in humans, above the 20% threshold and supportive of high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Naltrexone, the closest retrieved analogue, has an absolute oral bioavailability of about 5%, but this low value is associated with its phenolic 3-OH and N-cyclopropylmethyl substituents, which are absent in the query's 3-methoxy-N-methyl structure; therefore this contradictory evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 3-methoxy-N-methyl-14-hydroxy-6-keto morphinan. Multiple close morphinan analogues with direct human absolute oral bioavailability measurements—codeine (42-71%), nalmefene (41-53%), samidorphan (69%), ethylmorphine (74%), diamorphine (45.6-64.5%), and noscapine (30%)—support F >= 20%. The closest analogue naltrexone has low oral bioavailability, but its low F is mechanistically tied to the phenolic 3-OH and N-cyclopropylmethyl groups that the query does not share. The query's 3-methoxy/N-methyl substitution pattern aligns with high-oral-bioavailability opioids, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for oxycodone itself is present in the evidence set; the prediction relies on close structural analogues.",
    "Naltrexone's low-bioavailability evidence is structurally close but mechanistically less transferable because of key substituent differences."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

